import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0001: Generic Node, Trait-Based Capabilities, and Plugin-Driven Canonical Kit","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/archived/0001-generic-node-and-plugin-driven-canonical-kit.md","filePath":"vendored/handl/project/adrs/archived/0001-generic-node-and-plugin-driven-canonical-kit.md"}`),a={name:`handl/project/adrs/archived/0001-generic-node-and-plugin-driven-canonical-kit.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0001-generic-node-trait-based-capabilities-and-plugin-driven-canonical-kit" tabindex="-1">ADR-0001: Generic Node, Trait-Based Capabilities, and Plugin-Driven Canonical Kit <a class="header-anchor" href="#adr-0001-generic-node-trait-based-capabilities-and-plugin-driven-canonical-kit" aria-label="Permalink to “ADR-0001: Generic Node, Trait-Based Capabilities, and Plugin-Driven Canonical Kit”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The Handl platform currently defines concrete canonical implementations in three dedicated crates:</p><ul><li><code>handl-ast-canonical</code> — concrete expression, statement, pattern, type, and field nodes.</li><li><code>handl-lexer-canonical</code> — concrete token kind <code>CanonicalKind</code> and the canonical lexer.</li><li><code>handl-parser-canonical</code> — concrete recursive-descent parser with a hard-coded <code>CanonicalGrammar</code>.</li></ul><p>These crates are widely depended upon by plugins, libraries, hosts, and the root workspace package. They were a pragmatic starting point, but they make the canonical language a monolith rather than a composition of independent features.</p><p>We want the canonical language to be a curated kit (<code>kit-canonical</code>) assembled from small, composable plugins. The same capability model should apply to AST nodes, lexer tokens, grammar rules, and eventually runtime value types.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>We will:</p><ol><li>Define <strong>one generic <code>Node</code> type</strong> in <code>handl-ast</code>. Concrete node shapes will be provided by plugins. A language only includes the node shapes it loads.</li><li>Model <strong>capabilities as Rust traits</strong>. A node, token, grammar rule, or value type implements zero or more capability traits (<code>Expr</code>, <code>Stmt</code>, <code>Pattern</code>, <code>TokenKind</code>, <code>GrammarRule</code>, <code>Addable</code>, <code>Comparable</code>, etc.).</li><li>Make <strong>tokens, node shapes, and grammar rules pluggable at the smallest useful unit</strong>. Each canonical token, AST node, and grammar rule becomes a tiny plugin that the kit composes.</li><li>Turn <code>kit-canonical</code> into a <strong>curated plugin bundle</strong>, not the implementation itself.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="base-crates-become-pure-abstractions" tabindex="-1">Base crates become pure abstractions <a class="header-anchor" href="#base-crates-become-pure-abstractions" aria-label="Permalink to “Base crates become pure abstractions”">​</a></h3><table tabindex="0"><thead><tr><th>crate</th><th>new responsibility</th></tr></thead><tbody><tr><td><code>handl-ast</code></td><td>defines <code>Node</code> and per-shape node capabilities</td></tr><tr><td><code>handl-lexer</code></td><td>defines <code>Token</code>, <code>Lexer</code>, and <code>TokenKind</code> capability trait</td></tr><tr><td><code>handl-parser</code></td><td>defines <code>Parser</code>, <code>Grammar</code>, and <code>GrammarRule</code> capability trait</td></tr></tbody></table><h3 id="canonical-implementation-becomes-plugins" tabindex="-1">Canonical implementation becomes plugins <a class="header-anchor" href="#canonical-implementation-becomes-plugins" aria-label="Permalink to “Canonical implementation becomes plugins”">​</a></h3><p>Existing <code>*-canonical</code> crates will be split into the smallest composable plugins, for example:</p><table tabindex="0"><thead><tr><th>domain</th><th>example plugins</th></tr></thead><tbody><tr><td>AST node shapes</td><td><code>plugin-ast-call</code>, <code>plugin-ast-index</code>, <code>plugin-ast-pipe</code>, <code>plugin-ast-assign</code>, <code>plugin-ast-let</code>, <code>plugin-ast-match</code></td></tr><tr><td>Token kinds</td><td><code>plugin-token-number</code>, <code>plugin-token-string</code>, <code>plugin-token-identifier</code>, <code>plugin-token-comment</code></td></tr><tr><td>Grammar rules</td><td><code>plugin-grammar-call</code>, <code>plugin-grammar-index</code>, <code>plugin-grammar-pipe</code>, <code>plugin-grammar-assign</code>, <code>plugin-grammar-let</code>, <code>plugin-grammar-match</code></td></tr><tr><td>Value type families</td><td><code>plugin-value-integer</code>, <code>plugin-value-string</code>, <code>plugin-value-decimal</code></td></tr></tbody></table><p><code>kit-canonical</code> will become a manifest that registers the curated set of these tiny plugins.</p><h3 id="value-types-use-the-same-model" tabindex="-1">Value types use the same model <a class="header-anchor" href="#value-types-use-the-same-model" aria-label="Permalink to “Value types use the same model”">​</a></h3><p>Runtime value types will also be assembled from capabilities (<code>Addable</code>, <code>Comparable</code>, <code>Hashable</code>, <code>Serializable</code>, etc.). Plugins can introduce new value families, and target-specific representations (native, JS, WASM) are selected by the compiler.</p><h2 id="migration-plan" tabindex="-1">Migration plan <a class="header-anchor" href="#migration-plan" aria-label="Permalink to “Migration plan”">​</a></h2><ol><li><strong>Genericize <code>handl-ast</code></strong>: replace <code>Expr&lt;NonFunctionValue&gt;</code> with a single <code>Node</code> type and per-shape node traits.</li><li><strong>Genericize <code>handl-lexer</code></strong>: make <code>TokenKind</code> a plugin trait; remove concrete <code>CanonicalKind</code> from the base crate.</li><li><strong>Genericize <code>handl-parser</code></strong>: make <code>Grammar</code> composable from <code>GrammarRule</code> plugins.</li><li><strong>Create canonical plugins</strong>: extract canonical nodes, token kinds, and grammar rules into per-shape plugins such as <code>plugin-ast-*</code>, <code>plugin-token-*</code>, <code>plugin-grammar-*</code>, and <code>plugin-value-*</code>.</li><li><strong>Rewrite <code>kit-canonical</code></strong>: make it a host that loads the canonical plugin manifest.</li><li><strong>Migrate dependents</strong>: update plugins, libraries, and hosts to depend on the generic base crates or on <code>kit-canonical</code>.</li><li><strong>Delete <code>ast-canonical</code>, <code>lexer-canonical</code>, and <code>parser-canonical</code></strong> once the kit and all dependents are moved.</li></ol><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li><strong>Keep <code>*-canonical</code> crates</strong>: rejected because they make the canonical language a monolith that cannot be extended or subset by other kits.</li><li><strong>Use runtime capability descriptors instead of Rust traits</strong>: rejected because we want zero-cost static dispatch and trait-based type safety.</li><li><strong>One crate per canonical feature instead of tiny plugins</strong>: rejected because it breaks the plugin boundary and makes the kit less composable.</li></ul><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to “Implementation status”">​</a></h2><ul><li><code>handl-ast</code> now provides the generic <code>Node</code> type and per-shape node capability traits; concrete node shapes live in <code>plugin-ast-*</code> crates.</li><li><code>handl-lexer</code> and <code>handl-parser</code> have been genericized to <code>Token</code>/<code>Lexer</code> and <code>Parser</code>/<code>Grammar</code> abstractions with <code>TokenKind</code> and <code>GrammarRule</code> capability traits.</li><li><code>kit-canonical</code> has been rewritten as a curated plugin manifest rather than a concrete implementation crate.</li><li><code>handl-ast-canonical</code>, <code>handl-lexer-canonical</code>, and <code>handl-parser-canonical</code> crates have been removed.</li></ul><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to “Related work”">​</a></h2><ul><li>Composable value types design</li><li><code>docs/explanations/design-principles.md</code></li><li><code>kit-canonical</code> crate manifest</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};